begin;
create or replace function public.assign_fleet_metric(p_metric_definition_id uuid,p_target_type text,p_target_id uuid default null)
returns public.fleet_metric_assignments language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare d public.fleet_metric_definitions; v public.fleet_metric_assignments; t text:=lower(trim(p_target_type)); begin if auth.uid() is null then raise exception 'authentication required'; end if; select * into d from public.fleet_metric_definitions where id=p_metric_definition_id; if not found then raise exception 'Fleet metric definition not found'; end if; if not public.fleet_metric_controller_authorized(d.business_id) then raise exception 'Fleet controller authorization required'; end if; if t not in ('fleet','driver','vehicle','route') then raise exception 'Invalid Fleet metric target type'; end if; if (t='fleet')<>(p_target_id is null) then raise exception 'Target id mismatch'; end if; insert into public.fleet_metric_assignments(metric_definition_id,target_type,target_id) values(p_metric_definition_id,t,p_target_id) returning * into v; return v; end $$;
commit;
